#include <iostream>
using namespace std;
class AttendanceManager; class Classroom{private:string className;int totalStudents,presentStudents;bool attendanceStatus;public:Classroom(string n,int t,int p,bool s):className(n),totalStudents(t),presentStudents(p),attendanceStatus(s){}friend class AttendanceManager;};
class AttendanceManager{public:void displayInfo(Classroom&c){cout<<"Class: "<<c.className<<"\nTotal: "<<c.totalStudents<<"\nPresent: "<<c.presentStudents<<"\nAbsent: "<<c.totalStudents-c.presentStudents<<"\nStatus: "<<(c.attendanceStatus?"Completed":"Not Completed")<<endl;}void updatePresentStudents(Classroom&c,int p){if(p>=0&&p<=c.totalStudents)c.presentStudents=p;}void markAttendanceCompleted(Classroom&c){c.attendanceStatus=true;}void displayAttendanceStatus(Classroom&c){cout<<(c.attendanceStatus?"Completed":"Not Completed")<<endl;}void displayAbsentStudents(Classroom&c){cout<<"Absent: "<<c.totalStudents-c.presentStudents<<endl;}};
int main(){Classroom c("CSE B1",60,52,false);AttendanceManager m;m.displayInfo(c);m.updatePresentStudents(c,55);m.markAttendanceCompleted(c);m.displayAttendanceStatus(c);m.displayAbsentStudents(c);m.displayInfo(c);return 0;}
